#[inductive(update_done)]
fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    assert forall |node_id| #[trigger] post.combiner.contains_key(node_id)
        implies post.wf_combiner_for_node_id(node_id) by {
        assert(post.combiner[node_id] == pre.combiner[node_id]);
        assert(pre.wf_combiner_for_node_id(node_id));
        match post.combiner[node_id] {
            CombinerState::Placed { queued_ops } => {
                assert forall |r| #[trigger] pre.local_updates.contains_key(r)
                    ==> queued_ops.contains(r) ==> post.local_updates.contains_key(r)
                        && post.local_updates[r] === pre.local_updates[r] by {
                    if r == rid {
                        assert(pre.local_updates[rid].is_Applied());
                        assert(!queued_ops.contains(rid));
                    }
                }
                LogRangeMatchesQueue_update_change_2(queued_ops, post.log, 0,
                    post.local_versions[node_id], post.tail, node_id,
                    pre.local_updates, post.local_updates);
            }
            CombinerState::LoadedLocalVersion { queued_ops, lversion } => {
                assert forall |r| #[trigger] pre.local_updates.contains_key(r)
                    ==> queued_ops.contains(r) ==> post.local_updates.contains_key(r)
                        && post.local_updates[r] === pre.local_updates[r] by {
                    if r == rid {
                        assert(pre.local_updates[rid].is_Applied());
                        assert(!queued_ops.contains(rid));
                    }
                }
                LogRangeMatchesQueue_update_change_2(queued_ops, post.log, 0, lversion,
                    post.tail, node_id, pre.local_updates, post.local_updates);
            }
            CombinerState::Loop { queued_ops, idx, lversion, tail } => {
                assert forall |r| #[trigger] pre.local_updates.contains_key(r)
                    ==> queued_ops.contains(r) ==> post.local_updates.contains_key(r)
                        && post.local_updates[r] === pre.local_updates[r] by {
                    if r == rid {
                        assert(pre.local_updates[rid].is_Applied());
                        assert(!queued_ops.contains(rid));
                    }
                }
                LogRangeMatchesQueue_update_change_2(queued_ops, post.log, idx, lversion,
                    tail, node_id, pre.local_updates, post.local_updates);
                assert forall |j| 0 <= j < idx
                    implies post.local_updates.contains_key(queued_ops[j])
                        && (post.local_updates[queued_ops[j]].is_Applied()
                            || post.local_updates[queued_ops[j]].is_Done()) by {
                    assert(pre.wf_combiner_for_node_id(node_id));
                }
            }
            CombinerState::UpdatedVersion { queued_ops, tail } => {
                assert forall |r| #[trigger] pre.local_updates.contains_key(r)
                    ==> queued_ops.contains(r) ==> post.local_updates.contains_key(r)
                        && post.local_updates[r] === pre.local_updates[r] by {
                    if r == rid {
                        assert(pre.local_updates[rid].is_Applied());
                        assert(!queued_ops.contains(rid));
                    }
                }
            }
            _ => {}
        }
    }
}

